def record(id, title, section, subtype, start, end, region, languages, author, description, source, *, existing=False, alternate=None, manuscripts="No physical witness has yet been linked to this work record."):
    category = ("LITERATURE / CULTURAL INFLUENCE — NON-SCRIPTURAL" if section == "Religious literature" else subtype)
    base = {
        "id": id, "title": title,
        "traditionId": "religious-literature" if section == "Religious literature" else "gnostic-hermetic-esoteric",
        "tradition": "Literature / Cultural Influence" if section == "Religious literature" else "Esoteric and occult literature",
        "category": category,
        "canonStatus": "Literary work; explicitly non-scriptural" if section == "Religious literature" else "Historical esoteric work; not classified as scripture and not evidence that described operations are effective",
        "startDate": start, "endDate": end,
        "dateConfidence": "Approximate work chronology; consult the linked catalog or edition for witness-specific dating",
        "region": region, "lat": None, "lng": None, "languages": languages,
        "author": author,
        "description": description,
        "historicalContext": "Atlas presents this as literature and historical evidence. Descriptions of supernatural beings, magic, witchcraft, or cosmology report the source's contents and reception; they do not verify supernatural efficacy.",
        "manuscripts": manuscripts,
        "themes": ["ritual", "magic"] if section != "Religious literature" else ["afterlife", "evil", "salvation"],
        "sourceStatus": "Source-linked metadata; scholarly review pending; no operational instructions extracted" if section != "Religious literature" else "Metadata only; public-domain source linked where available; scholarly review pending",
        "copyright": "Metadata only; linked repository terms govern source access" if section != "Religious literature" else "Work is public domain; edition rights are recorded separately",
        "sourceUrl": source, "metadataSources": [source], "editionId": None, "confidence": "Unreviewed",
        "subcollection": section,
    }
    if alternate: base["alternateTitles"] = alternate
    return base

