editions=[]; passages=[]
for gid,text_id,title,translator,language in edition_config:
    path=PD/f"{gid}.txt"; raw=path.read_text(encoding="utf-8-sig").replace("\r\n","\n").replace("\r","\n")
    start=re.search(r"\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG EBOOK[^\n]*\*\*",raw,re.I)
    end=re.search(r"\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG EBOOK",raw,re.I)
    if not start or not end: raise ValueError(f"Missing Gutenberg markers: {gid}")
    body=raw[start.end():end.start()].strip(); chunks=[]; buffer=""
    for block in re.split(r"\n\s*\n",body):
        if len(buffer)+len(block)>1800 and buffer: chunks.append(buffer.strip()); buffer=""
        buffer += block.strip()+"\n\n"
    if buffer.strip(): chunks.append(buffer.strip())
    eid=f"pg-{gid}-phase12"
    for idx,chunk in enumerate(chunks,1):
        passages.append({"id":f"{eid}-{idx}","textId":text_id,"editionId":eid,"sequence":idx,"reference":f"Edition segment {idx}","content":chunk,"sourceUrl":PG.format(gid),"themes":[],"contentType":"Unknown"})
    editions.append({"sourceFile":f"{gid}.txt","sourceSections":None,"id":eid,"textId":text_id,"title":title,"translator":translator,"sourceUrl":PG.format(gid),"downloadUrl":f"https://www.gutenberg.org/cache/epub/{gid}/pg{gid}.txt","license":"Public domain in the USA. Project Gutenberg license retained in the source file; check local restrictions elsewhere.","language":language,"sha256":hashlib.sha256(raw.encode()).hexdigest(),"passageCount":len(chunks),"complete":True,"note":"Complete Project Gutenberg edition body. Atlas segment numbers are navigation locators, not original line, canto, or scene numbers. This literary edition is non-scriptural."})
    target=next(r for r in rows if r["id"]==text_id); target["editionId"]=eid; target["sourceStatus"]="Complete public-domain literary edition available"

